    """UNIT 1a-w: trapezoid vs S7 on the widening rows (prediction PREDICTION-S89-UNIT1A-W.md)."""
    p = PRED.replace('PAIR', 'W'); want = open(p.replace('.md', '.sha256')).read().split()[0]
