        t += tr == b; s += s7 == b; diff += tr != s7
        if tr != b: bad.append((Z, r1['tag'], r1['J'], r2['tag'], r2['J']))
        if r1['dg_dl'] <= -0.3: w3.append((Z, r1['tag'], r1['J']))
        print(f"  Z={Z} r1 {r1['tag']} {r1['dg_dl']:+.3f} r2 {r2['tag']} {r2['dg_dl']:+.3f} banked {o['banked_dg_dl']:+.3f} trap {int(tr):+d} s7 {int(s7):+d}")
    print(f"  W1 trapezoid {t}/{len(zs)} fail {bad}\n  W2 S7 {s}/{len(zs)}, rules differ at {diff}\n  W3 rank-1 dg/dl <= -0.3: {w3}\n  W4 regions seen {sorted(regs)}")
    return 0


if __name__ == '__main__' and sys.argv[1:2] == ['scorew']:
    sys.exit(scorew([int(x) for x in sys.argv[2:]]))
